// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function testFuzz_property(uint96 amount) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(amount > 0);
        ReentrantCaller caller = new ReentrantCaller(address(c));
        vm.deal(address(caller), amount);
        caller.deposit{value: amount}();
        uint256 observed = caller.withdrawAndObserve();
        assertTrue(observed == 0);
    }
}

contract ReentrantCaller {
    Reentrance internal c;
    uint256 public observedBalance;

    constructor(address _c) {
        c = Reentrance(_c);
    }

    receive() external payable {
        observedBalance = c.getBalance(address(this));
    }

    function deposit() external payable {
        c.addToBalance{value: msg.value}();
    }

    function withdrawAndObserve() external returns (uint256) {
        observedBalance = type(uint256).max;
        c.withdrawBalance();
        return observedBalance;
    }
}
